import{_ as s,l as c,o as a,c as d,v as o,p as n,x as r,d as i,i as l,S as p}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"RISC-V 压缩指令","description":"","frontmatter":{"title":"RISC-V 压缩指令","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/riscv-compressed.md","filePath":"cs/riscv-compressed.md","lastUpdated":1789023840000}'),h={name:"cs/riscv-compressed.md"};function C(E,e,m,u,A,_){const t=c("Mermaid");return a(),d("div",null,[e[1]||(e[1]=o('<h1 id="risc-v-压缩指令" tabindex="-1">RISC-V 压缩指令 <a class="header-anchor" href="#risc-v-压缩指令" aria-label="Permalink to &quot;RISC-V 压缩指令&quot;">​</a></h1><div class="epigraph"><p>`C` 扩展用 16 位编码最常见的操作：码密度靠近 CISC，译码仍只要区分 16/32，不必回到 x86 的前缀迷宫。</p><footer>—— 据 The RISC-V Instruction Set Manual, Volume I；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/rvv-vector">上一课</a>加宽了数据通路。取指带宽与 I-cache 仍吃<strong>指令字节</strong>。缺口是 <strong>RVC</strong>：常见 <code>addi</code>/<code>lw</code>/<code>jal</code> 的短编码，与 <a href="/cs/arm-vs-riscv">ARM vs RISC-V</a> 里「A64 不定长、RV 可选混长」那一行兑现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯 32 位对齐浪费 I-cache。RVC：最低两位不是 <code>11</code> 则为 16 位指令，映射到 32 位语义超集（不是新功能）。缺口不是向量 VL，而是<strong>对齐</strong>：16 位指令可落在半字，32 位指令仍须 16 位对齐但不能跨过非法边界——取指单元要能吞两种。</p><p>没有 RVC 的实现只跑 32 位，软件需统一 ABI（psABI 规定是否含 C）。与 x86 变长：长度种类少得多，没有 ModR/M 链。</p><h3 id="压缩不是-thumb-2-的全部历史" tabindex="-1">压缩不是 Thumb-2 的全部历史 <a class="header-anchor" href="#压缩不是-thumb-2-的全部历史" aria-label="Permalink to &quot;压缩不是 Thumb-2 的全部历史&quot;">​</a></h3><p>ARM Thumb 有自己的模式切换与编码表。RVC 与 32 位在同一用户模式混排，不靠 <code>j</code> 进「压缩模式」。把 RVC 当另一套特权，链接器会配错。</p><p><span class="marginnote">RISC-V ISA Manual 的 C 扩展章。Patterson/Hennessy 用压缩提高密度。本课不背 16 位 opcode 图。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>汇编器自动选 C 形式或 <code>.option rvc</code>。反汇编要按 16/32 扫描，类似简化版<a href="/cs/x86-64-encoding">长度解码</a>。异常：<code>pc</code> 仍指向指令首字节，16 位指令的 <code>pc+2</code>。与 JAL 范围：压缩跳转位移更短，远目标用 32 位 <code>jal</code>。</p>',11)),(a(),n(p,null,{default:r(()=>[l(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREQ%5B%22%E9%AB%98%E9%A2%91%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20C16%5B%2216%20%E4%BD%8D%20C%20%E7%BC%96%E7%A0%81%22%5D%0A%20%20RARE%5B%22%E5%85%B6%E4%BD%99%22%5D%20--%3E%20I32%5B%2232%20%E4%BD%8D%22%5D%0A%20%20C16%20--%3E%20FETCH%5B%2216%2F32%20%E5%AF%B9%E9%BD%90%E5%8F%96%E6%8C%87%22%5D%0A%20%20I32%20--%3E%20FETCH%0A%20%20FETCH%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%A1%B5%E8%A1%A8%E4%B8%8E%20PC%20%E5%AF%B9%E9%BD%90%E5%8F%A6%E4%B8%80%E5%B1%82%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>静态密度增益典型两成量级（程序依赖），本课不编造百分比保证。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课 Sv39 管虚拟地址，与指令长度正交，但取指跨页要两条翻译。位操作扩展也是 32 位编码为主。本课把「RISC 也能密度」钉住，完成与 x86 对照的密度轴。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讨论 Zc 进一步压缩子集的全部别名。不把压缩当加密。不保证所有扩展都有 C 别名。</p><p>后课默认：RVC 用 16 位别名常见指令；取指按 2 字节步进识别 16/32。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>C</code> 提高码密度，语义仍是 32 位指令的子集。</li><li>混长只有两种，不是 x86 前缀树。</li><li>与 A64 纯 32 位是明确差异。</li><li>出处：RISC-V ISA Manual, Vol. I；Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const R=s(h,[["render",C]]);export{I as __pageData,R as default};
